+  it('should not accept a legacy signature through the retupling collision', async () => {
+    const legacy = await signLegacy({
+      approvalId: 'approval-1',
+      toolCallId: 'call-1',
+      toolName: 'searchDocs\ndeleteFile',
+      input: { path: '/tmp/target' },
